import{_ as o,c as a,o as i,aj as t}from"./chunks/framework.BlveriQe.js";const p=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md"}'),r={name:"changelog.md"};function n(s,e,d,c,l,h){return i(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to “Changelog”">​</a></h1><p>User-visible changes in each production release of the Primitive platform: new capabilities, additions and changes to the client APIs and the CLI, and fixes that change behavior you can observe. Internal work — refactoring, infrastructure, dependency bumps — is not listed. Entries are newest first; each date is a production release.</p><h2 id="_2026-07-24" tabindex="-1">2026-07-24 <a class="header-anchor" href="#_2026-07-24" aria-label="Permalink to “2026-07-24”">​</a></h2><h3 id="new" tabindex="-1">New <a class="header-anchor" href="#new" aria-label="Permalink to “New”">​</a></h3><ul><li><strong>Conditional document writes.</strong> Single-document <code>save</code>, <code>patch</code>, and <code>delete</code> accept <code>upsertOn</code>, <code>precondition</code> (compare-and-set), and <code>ifNotExists</code>; bulk updates accept a per-operation <code>precondition</code>. A failed guard rejects the write with <code>CONDITION_NOT_MET</code> and rolls back the whole batch. Preconditions are field-equality only.</li><li><strong>Multiple sign-in providers per account.</strong> A user can link more than one OAuth provider (for example Google and Apple); signing in with either resolves the same account.</li><li><strong>Error-event analytics.</strong> Failures are recorded as fingerprinted error events in a dedicated dataset, queryable with the <code>errors.groups</code> query type — via the HTTP API, the workflow <code>analytics</code> step, or <code>primitive analytics errors-groups</code>.</li><li><strong>Parameterized workflow fragments.</strong> A workflow fragment include accepts parameters, so one fragment serves multiple call sites.</li><li><strong><code>primitive blob-buckets head</code></strong> reads a blob&#39;s metadata without downloading its content.</li><li><strong><code>primitive connections list</code></strong> inspects an app&#39;s active client connections.</li></ul><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to “Changed”">​</a></h3><ul><li><strong>Unified list pagination.</strong> Every list endpoint returns <code>{ items, hasMore, nextCursor }</code>. The previous <code>cursor</code> field and per-endpoint array keys remain as deprecated aliases for one deprecation window — migrate readers to <code>items</code> and <code>nextCursor</code>.</li><li><strong>Stricter list-input validation.</strong> Zero, negative, or non-integer <code>limit</code> values and malformed cursors now return <code>400</code> instead of being silently coerced.</li></ul><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to “Fixed”">​</a></h3><ul><li>The JavaScript client advances through every page of a list result instead of stopping after the first.</li><li>Users who linked a second sign-in provider are no longer locked out of the first.</li><li>A just-created document appears in the creator&#39;s owned-documents list immediately.</li><li>Group-membership reads paginate fully instead of silently truncating for users with many memberships.</li><li>CLI: date-time field values are serialized correctly on <code>primitive config push</code>, and workflow lock configuration (<code>[workflow.lock]</code>) survives config push and pull.</li><li>Swift client: <code>waitForWriteConfirmation</code> and <code>waitForInSync</code> wait for the write to actually be confirmed, and reconnect backoff no longer overflows during long outages.</li></ul>',9)])])}const u=o(r,[["render",n]]);export{p as __pageData,u as default};
